NETWORK_TEMPLATES.forEach(tpl => {
  if (!tpl.svg && tpl.iconKey) {
    tpl.svg = TEMPLATE_ICONS[tpl.iconKey] || TEMPLATE_ICONS[tpl.baseId] || TEMPLATE_ICONS['website'];
  }
});
